<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_login(); require_clothing_warehouse_access();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['product_id'];$count=(float)$_POST['counted_quantity'];$pdo->beginTransaction();$s=$pdo->prepare('SELECT current_quantity,location_id FROM products WHERE id=? FOR UPDATE');$s->execute([$id]);$product=$s->fetch(PDO::FETCH_ASSOC);if(!$product){$pdo->rollBack();exit('Product not found.');}$difference=$count-(float)$product['current_quantity'];if($difference!=0){$code='ADJ-'.date('Ymd').'-'.random_int(100,999);$pdo->prepare("INSERT INTO stock_movements(movement_code,product_id,location_id,movement_type,quantity,reference_no,notes,created_by) VALUES(?,?,?,'Adjustment',?,?,?,?)")->execute([$code,$id,$product['location_id'],abs($difference),'STOCK-TAKE',trim($_POST['notes'])?:'Physical stock take',$_SESSION['user']['id']]);$pdo->prepare('UPDATE products SET current_quantity=? WHERE id=?')->execute([$count,$id]);}$pdo->commit();flash('Stock take saved.');header('Location:stock_take.php');exit;}$products=$pdo->query('SELECT p.*,l.location_code FROM products p LEFT JOIN warehouse_locations l ON l.id=p.location_id WHERE p.status="Active" ORDER BY p.product_name')->fetchAll(PDO::FETCH_ASSOC);$page_title='Stock Take';require __DIR__.'/../includes/header.php';?><div class="mb-4"><h1 class="page-heading"><?=e(t('stock_take'))?></h1><p class="page-subtitle mb-0"><?=e(t('stock_take_note'))?></p></div><div class="panel table-responsive"><table class="table"><thead><tr><th><?=e(t('product_code'))?></th><th><?=e(t('product_name'))?></th><th><?=e(t('storage_location'))?></th><th><?=e(t('system_quantity'))?></th><th><?=e(t('stock_count'))?></th><th><?=e(t('notes'))?></th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><td><?=e($p['product_code'])?></td><td><?=e($p['product_name'])?></td><td><?=e($p['location_code'])?></td><td><?=number_format($p['current_quantity'],0).' '.e($p['unit'])?></td><td><input class="form-control form-control-sm" type="number" min="0" step="1" name="counted_quantity" value="<?=number_format((float)$p['current_quantity'],0,'.','')?>"></td><td><input class="form-control form-control-sm" name="notes"></td><td><button class="btn btn-sm btn-primary"><?=e(t('save_stock_take'))?></button></td></form></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../includes/footer.php'; ?>
